template <ggml_type type, int J, bool fallback, ggml_prec prec_src1>
static void launch_mul_mat_q_table(ggml_backend_cuda_context & ctx, const char * const * table, uint32_t table_off, const mmq_args & args, cudaStream_t stream) {
    const int id = ggml_cuda_get_device();
    const int cc = ggml_cuda_info().devices[id].cc;
    const int nsm = ggml_cuda_info().devices[id].nsm;
    const int warp_size = ggml_cuda_info().devices[id].warp_size;

    const ggml_cuda_mmq_config config = ggml_cuda_mmq_get_config(type, J, fallback, cc, prec_src1);
    GGML_ASSERT(config.nthreads % warp_size == 0);
    const int nwarps = config.nthreads / warp_size;
    const int nbytes_shared = mmq_get_nbytes_shared(config, cc);

    const dim3 block_dims(warp_size, nwarps, 1);

    CUDA_SET_SHARED_MEMORY_LIMIT((mul_mat_q_table<type, J, false, prec_src1>), nbytes_shared);
    CUDA_SET_SHARED_MEMORY_LIMIT((mul_mat_q_table<type, J,  true, prec_src1>), nbytes_shared);

    const int nty  = (args.nrows_x   + config.I - 1) / config.I;
    const int ntx  = (args.ncols_max + config.J - 1) / config.J;
    const int ntzw = args.nchannels_y * args.nsamples_y;
    const dim3 block_nums_xy_tiling(nty, ntx, ntzw);

    GGML_ASSERT(args.nchannels_y % args.nchannels_x == 0);
    GGML_ASSERT(args.nsamples_y  % args.nsamples_x  == 0);
    const int channel_ratio = args.nchannels_y / args.nchannels_x;
    const int sample_ratio  = args.nsamples_y  / args.nsamples_x;

    const uint3 blocks_per_ne00_fd = init_fastdiv_values(args.ncols_x / ggml_cuda_type_traits<type>::qk);
    const uint3 ntx_fd             = init_fastdiv_values(ntx);
    const uint3 nchannels_y_fd     = init_fastdiv_values(args.nchannels_y);
    const uint3 nsamples_y_fd      = init_fastdiv_values(args.nsamples_y);
    const uint3 channel_ratio_fd   = init_fastdiv_values(channel_ratio);
    const uint3 sample_ratio_fd    = init_fastdiv_values(sample_ratio);

    if (!config.stream_k) {
        mul_mat_q_table<type, J, fallback, prec_src1><<<block_nums_xy_tiling, block_dims, nbytes_shared, stream>>>
            (table, table_off, args.y, args.ids_dst, args.expert_bounds, args.dst, nullptr, args.y_scale,
             blocks_per_ne00_fd, args.nrows_x, args.ncols_dst, args.stride_row_x, args.ncols_y, args.nrows_dst,
             channel_ratio_fd, nchannels_y_fd, args.stride_channel_x, args.stride_channel_y, args.stride_channel_dst,
             sample_ratio_fd, nsamples_y_fd, args.stride_sample_x, args.stride_sample_y, args.stride_sample_dst,
             ntx_fd);
        return;
    }

    // For the stream-k kernel it is possible to run it with tiling by setting the number of CUDA blocks equal to the number of tiles.
    // This is worthwhile if the efficiency of tiling is high and skipping the fixup kernel is more important.
    const int ntiles_dst = ntx * nty * ntzw;
    const int tiles_nwaves = (ntiles_dst + nsm - 1) / nsm;
    const int tiles_efficiency_percent = 100 * ntiles_dst / (nsm*tiles_nwaves);

    GGML_ASSERT(ntiles_dst * blocks_per_ne00_fd.z < (1 << 30)); // Assert that variable kbc will not overflow.

    const int nwork = ntiles_dst * ((args.ncols_x + config.K_vram - 1) / config.K_vram); // Maximum number of CUDA blocks that can do useful work.
    const dim3 block_nums_stream_k(GGML_CUDA_CC_IS_NVIDIA(cc) && tiles_efficiency_percent >= 90 ? ntiles_dst : std::min(nsm, nwork), 1, 1);

    const bool fixup_needed = ntiles_dst % block_nums_stream_k.x != 0;

    ggml_cuda_pool & pool = ctx.pool(id);
    ggml_cuda_pool_alloc<float> tmp_fixup(pool);
    if (fixup_needed) {
        tmp_fixup.alloc(block_nums_stream_k.x * config.J*config.I);
    }

    const dim3 block_nums_fixup(block_nums_stream_k.x, config.I/warp_size, 1);
    const dim3 block_dims_fixup(block_dims.x, block_dims.y/2, block_dims.z);

    mul_mat_q_table<type, J, fallback, prec_src1><<<block_nums_stream_k, block_dims, nbytes_shared, stream>>>
        (table, table_off, args.y, args.ids_dst, args.expert_bounds, args.dst, tmp_fixup.ptr, args.y_scale,
         blocks_per_ne00_fd, args.nrows_x, args.ncols_dst, args.stride_row_x, args.ncols_y, args.nrows_dst,
         channel_ratio_fd, nchannels_y_fd, args.stride_channel_x, args.stride_channel_y, args.stride_channel_dst,
         sample_ratio_fd, nsamples_y_fd, args.stride_sample_x, args.stride_sample_y, args.stride_sample_dst,
         ntx_fd);

    if (!fixup_needed) {
        return;
    }

    CUDA_CHECK(cudaGetLastError());
    mul_mat_q_stream_k_fixup<type, J, fallback, prec_src1><<<block_nums_fixup, block_dims_fixup, 0, stream>>>
        (args.ids_dst, args.expert_bounds, args.dst, tmp_fixup.ptr, blocks_per_ne00_fd, args.nrows_x, args.ncols_dst,
         args.nrows_dst, nchannels_y_fd, args.stride_channel_dst, nsamples_y_fd, args.stride_sample_dst,
         ntx_fd);
}

template <ggml_type type, bool fallback, ggml_prec prec_src1>
void mul_mat_q_table_switch_J(ggml_backend_cuda_context & ctx, const char * const * table, uint32_t table_off, const mmq_args & args, cudaStream_t stream) {
    switch (args.J_best) {
        case   8:
            launch_mul_mat_q_table<type,   8, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  16:
            launch_mul_mat_q_table<type,  16, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  24:
            launch_mul_mat_q_table<type,  24, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  32:
            launch_mul_mat_q_table<type,  32, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  40:
            launch_mul_mat_q_table<type,  40, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  48:
            launch_mul_mat_q_table<type,  48, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  56:
            launch_mul_mat_q_table<type,  56, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  64:
            launch_mul_mat_q_table<type,  64, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  72:
            launch_mul_mat_q_table<type,  72, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  80:
            launch_mul_mat_q_table<type,  80, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  88:
            launch_mul_mat_q_table<type,  88, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case  96:
            launch_mul_mat_q_table<type,  96, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case 104:
            launch_mul_mat_q_table<type, 104, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case 112:
            launch_mul_mat_q_table<type, 112, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case 120:
            launch_mul_mat_q_table<type, 120, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        case 128:
            launch_mul_mat_q_table<type, 128, fallback, prec_src1>(ctx, table, table_off, args, stream);
            break;
        default:
            fprintf(stderr, "J_best=%d\n", args.J_best);
            GGML_ABORT("fatal error");
    }
}

